mapper.update:
UPDATE board_comment
SET 
	content = #{content},
	mdf_date = CURRENT_TIMESTAMP,
	mdf_user_id = #{sess_user_id}
WHERE comment_id = #{comment_id}
  AND user_id = #{sess_user_id}
  AND del_yn = 'N'

UPDATE board_comment
SET 
	del_yn = #{del_yn},
	mdf_date = CURRENT_TIMESTAMP,
	mdf_user_id = #{sess_user_id}
WHERE comment_id = #{comment_id}
  AND (
  	user_id = #{sess_user_id}
  	OR #{sess_is_admin} = 'Y'
  )

